WITH matched_keys AS (SELECT store_id, product_id FROM inventory EXCEPT ALL SELECT store_id, product_id FROM inventory WHERE quantity BETWEEN 130 AND 187), reconciled AS (SELECT s.* FROM inventory s JOIN matched_keys k ON s.store_id = k.store_id AND s.product_id = k.product_id) SELECT s.id, s.product_id, s.quantity, s.last_restock, (SELECT MAX(x.unit_price) FROM order_items x WHERE x.product_id = s.product_id) AS max_order_item_unit_price FROM reconciled s
